                          },
                        }"
                        :edit="isEdit"
                        path="Basic.personal-reference.address"
                        displayCondition=""
                        id="Basic.extension:personal-reference.extension:address.value[x]:valueString"
                        definition="http://ihris.org/fhir/StructureDefinition/external-applicant-profile#Basic.extension:personal-reference.extension:address.value[x]:valueString"
                        label="Reference Address"
                        min="1"
                        max="1"
                        :key="'pr-address-' + prIndex"
                      ></fhir-string>
                    </v-col>
                    <v-col cols="6">
                      <fhir-string
                        field="value[x]:valueString"
                        :slotProps="{
                          source: {
                            fromArray: true,
                            path: 'personal-reference.occupation',
                            data: form.personalReferences[prIndex].occupation,
                            index: prIndex,
                          },
                        }"
                        :edit="isEdit"
                        path="Basic.personal-reference.occupation"
                        displayCondition=""
                        id="Basic.extension:personal-reference.extension:occupation.value[x]:valueString"
                        definition="http://ihris.org/fhir/StructureDefinition/external-applicant-profile#Basic.extension:personal-reference.extension:occupation.value[x]:valueString"
                        label="Reference Occupation"
                        min="1"
                        max="1"
                        :key="'pr-occupation-' + prIndex"
                      ></fhir-string>
                    </v-col>
                    <v-col cols="6">
                      <fhir-string
                        field="value[x]:valueString"
                        :slotProps="{
                          source: {
                            fromArray: true,
                            path: 'personal-reference.period',
                            data: form.personalReferences[prIndex].period,
                            index: prIndex,
                          },
                        }"
                        :edit="isEdit"
                        path="Basic.personal-reference.period"
                        displayCondition=""
                        id="Basic.extension:personal-reference.extension:period.value[x]:valueString"
                        definition="http://ihris.org/fhir/StructureDefinition/external-applicant-profile#Basic.extension:personal-reference.extension:period.value[x]:valueString"
                        label="Period of knowing you"
                        min="1"
                        max="1"
                        :key="'pr-period-' + prIndex"
                      ></fhir-string>
                    </v-col>
                  </v-row>
                </v-card-text>
              </v-card>
            </v-col>

            <!-- ── COUNCIL REGISTRATION ────────────────────────────── -->
            <v-col cols="12">
              <div id="section-council" class="su-section-label">
                Council Registration
              </div>
            </v-col>
            <v-col cols="12" v-if="councilRegistrationRows.length === 0">
              <v-btn
                outlined
                small
                color="primary"
                @click="addCouncilRegistrationRow()"
              >
                <v-icon left small>mdi-plus</v-icon>
                Add Council Registration
              </v-btn>
            </v-col>
            <v-col
              cols="12"
              v-for="(crRow, crIndex) in councilRegistrationRows"
              :key="'cr-' + crIndex"
            >
              <v-card elevation="1" outlined>
                <v-system-bar
                  color="secondary"
                  dark
                  class="pa-4 white--text font-weight-bold"
                >
                  Council Registration {{ crIndex + 1 }}
                  <v-spacer></v-spacer>
                  <v-btn icon @click="removeCouncilRegistrationRow(crIndex)">
                    <v-icon>mdi-minus-circle</v-icon>
                  </v-btn>
                  <v-btn
                    v-if="crIndex === councilRegistrationRows.length - 1"
                    icon
                    @click="addCouncilRegistrationRow()"
                  >
                    <v-icon color="green">mdi-plus-circle</v-icon>
                  </v-btn>
                </v-system-bar>
                <v-card-text>
                  <v-row>
                    <v-col cols="6">
                      <fhir-choice
                        field="value[x]:valueCoding"
                        :slotProps="{
                          source: {
                            fromArray: true,
                            path: 'council-registration.council',
                            data: form.councilRegistrations[crIndex].council,
                            index: crIndex,
                          },
                        }"
                        :edit="isEdit"
                        :path="`Basic.council-registration[${crIndex}].council`"
                        displayCondition=""
                        id="Basic.extension:council-registration.extension:council.value[x]:valueCoding"
                        definition="http://ihris.org/fhir/StructureDefinition/external-applicant-profile#Basic.extension:council-registration.extension:council.value[x]:valueCoding"
                        label="Registration Council"
                        binding="http://ihris.org/fhir/ValueSet/council-valueset"
                        min="1"
                        max="1"
                        :key="'cr-council-' + crIndex"
                        @change="
                          (val) =>
                            (form.councilRegistrations[crIndex].council = val)
                        "
                      ></fhir-choice>
                    </v-col>
                    <v-col cols="6">
                      <fhir-string
                        field="value[x]:valueString"
                        :slotProps="{
                          source: {
                            fromArray: true,
                            path: 'council-registration.registration-number',
                            data:
                              form.councilRegistrations[crIndex]
                                .registrationNumber,
                            index: crIndex,
                          },
                        }"
                        :edit="isEdit"
                        :path="
                          `Basic.council-registration[${crIndex}].registration-number`
                        "
                        displayCondition=""
                        id="Basic.extension:council-registration.extension:registration-number.value[x]:valueString"
                        definition="http://ihris.org/fhir/StructureDefinition/external-applicant-profile#Basic.extension:council-registration.extension:registration-number.value[x]:valueString"
                        label="Registration Number"
                        min="1"
                        max="1"
                        :key="'cr-regnum-' + crIndex"
                      ></fhir-string>
                    </v-col>
                    <v-col cols="6">
                      <fhir-date
                        field="value[x]:valueDate"
                        :slotProps="{
                          source: {
                            fromArray: true,
                            path: 'council-registration.registration-date',
                            data:
                              form.councilRegistrations[crIndex]
                                .registrationDate,
                            index: crIndex,
                          },
                        }"
                        :edit="isEdit"
                        :path="
                          `Basic.council-registration[${crIndex}].registration-date`
                        "
                        displayCondition=""
                        id="Basic.extension:council-registration.extension:registration-date.value[x]:valueDate"
                        definition="http://ihris.org/fhir/StructureDefinition/external-applicant-profile#Basic.extension:council-registration.extension:registration-date.value[x]:valueDate"
                        label="First Registration Date"
                        min="0"
                        max="1"
                        :key="'cr-regdate-' + crIndex"
                      ></fhir-date>
                    </v-col>
                    <v-col cols="6">
                      <fhir-choice
                        field="value[x]:valueCoding"
                        :slotProps="{
                          source: {
                            fromArray: true,
                            path: 'council-registration.license-status',
                            data:
                              form.councilRegistrations[crIndex].licenseStatus,
                            index: crIndex,
                          },
                        }"
                        :edit="isEdit"
                        :path="
                          `Basic.council-registration[${crIndex}].license-status`
                        "
                        displayCondition=""
                        id="Basic.extension:council-registration.extension:license-status.value[x]:valueCoding"
                        definition="http://ihris.org/fhir/StructureDefinition/external-applicant-profile#Basic.extension:council-registration.extension:license-status.value[x]:valueCoding"
                        label="License Status"
                        binding="http://ihris.org/fhir/ValueSet/license-status-valueset"
                        min="1"
                        max="1"
                        :key="'cr-licstatus-' + crIndex"
                        @change="
                          (val) =>
                            (form.councilRegistrations[
                              crIndex
                            ].licenseStatus = val)
                        "
                      ></fhir-choice>
                    </v-col>
                  </v-row>
                </v-card-text>
              </v-card>
            </v-col>

            <!-- ── PASSWORD (hidden in edit mode) ──────────────────── -->
            <template v-if="!editMode">
              <v-col cols="6">
                <v-text-field
                  v-model="form.password"
                  :type="showPassword ? 'text' : 'password'"
                  label="Password"
                  outlined
                  dense
                  :rules="passwordRules"
                  :append-icon="showPassword ? 'mdi-eye-off' : 'mdi-eye'"
                  @click:append="showPassword = !showPassword"
                ></v-text-field>
              </v-col>
              <v-col cols="6">
                <v-text-field
                  v-model="form.confirmPassword"
                  :type="showConfirm ? 'text' : 'password'"
                  label="Confirm Password"
                  outlined
                  dense
                  :rules="confirmPasswordRules"
                  :append-icon="showConfirm ? 'mdi-eye-off' : 'mdi-eye'"
                  @click:append="showConfirm = !showConfirm"
                ></v-text-field>
              </v-col>
            </template>
          </v-row>
        </ihris-questionnaire-section>

        <v-alert
          v-if="!editMode"
          type="info"
          dense
          outlined
          class="mx-4 mb-2"
          icon="mdi-information-outline"
        >
          Your <strong>username</strong> will be the email address you entered
          above.
        </v-alert>

        <v-card
          outlined
          class="mt-4 mb-6 pa-4 d-flex flex-column align-center"
          style="gap:12px;"
        >
          <div v-if="!editMode" class="body-2 grey--text">
            Already have an account?
            <v-btn
              text
              small
              color="teal darken-1"
              class="pa-0"
              @click="goToLogin"
              >Log in</v-btn
            >
          </div>
        </v-card>
      </v-form>
    </div>
    <v-snackbar
      v-model="snackbar.show"
      :color="snackbar.color"
      top
      right
      :timeout="4000"
    >
      <v-icon left small>{{
        snackbar.color === "success" ? "mdi-check-circle" : "mdi-alert-circle"
      }}</v-icon>
      {{ snackbar.text }}
      <template #action="{ attrs }">
        <v-btn text v-bind="attrs" @click="snackbar.show = false">Close</v-btn>
      </template>
    </v-snackbar>
  </div>
</template>

<script>
import { eventBus } from "@/main";
import processQuestionnaire from "../../mixins/processQuestionnaire";
export default {
  name: "Signup",
  props: ["queries"],
  mixins: [processQuestionnaire],

  data() {
    return {
      sectionMenu: [
        { id: "section-personal", title: "Personal Details" },
        { id: "section-father", title: "Father Particulars" },
        { id: "section-spouse", title: "Spouse Particulars" },
        { id: "section-declarations", title: "Declarations" },
        { id: "section-schools", title: "Schools Attended" },
        { id: "section-exams", title: "Examinations" },
        { id: "section-subjects", title: "Subjects Passed" },
        { id: "section-education", title: "Post-Secondary" },
        { id: "section-qualifications", title: "Qualifications" },
        { id: "section-employment", title: "Employment" },
        { id: "section-references", title: "References" },
        { id: "section-council", title: "Council Reg." },
      ],
      url: "http://ihris.org/fhir/Questionnaire/external-applicant",
      fhir: {},
      fhirId: "",
      profile:
        "http://ihris.org/fhir/StructureDefinition/external-applicant-profile",
      isEdit: true,
      valid: false,
      saving: false,
      loading: false,
      snackbar: { show: false, text: "", color: "success" },
      form: {
        firstname: "",
        middlename: "",
        surname: "",
        email: "",
        phone: "",
        birthdate: "",
        gender: "",
        birthplace: "",
        maritalstatus: "",
        disabled: "",
        nationality: "",
        presentaddress: "",
        residence: "",
        nationalid: "",
        passportnumber: "",
        passportissuedate: "",
        passportexpirydate: "",
        passportissuecountry: "",
        borninlesotho: "",
        nameofchief: "",
        birthdistrict: "",
        tin: "",
        citizencertificatenumber: "",
        citizencertificateissuedate: "",
        fathername: "",
        fatherbirthplace: "",
        fatheroccupation: "",
        fatheraddress: "",
        spousename: "",
        spousenationality: "",
        convictedofcriminaloffense: "",
        dismissedfromservicebefore: "",
        postSecondaryEducation: [
          {
            institutionName: "",
            country: "",
            dateOfEntry: "",
            dateOfLeaving: "",
            qualificationLevel: "",
            qualificationName: "",
            qualificationNameOther: "",
            qualificationDate: "",
            specialized: "",
            specialization: "",
            isHighestQualification: "",
            distinctionsGained: [],
            nameKey: 0,
          },
        ],
        additionalQualifications: [],
        employmentHistory: [
          {
            employerCategory: null,
            governmentDepartment: "",
            grade: "",
            name: "",
            address: "",
            capacity: "",
            dutiesNature: "",
            startDate: "",
            endDate: "",
            salary: "",
            reasonForLeaving: "",
            noticePeriod: "",
            acting: null,
          },
        ],
        personalReferences: [
          {
            name: "",
            address: "",
            occupation: "",
            period: "",
          },
        ],
        schoolsAttended: [{ name: "", dateOfEntry: "", dateOfLeaving: "" }],
        examinationPassed: [
          { name: "", grade: "", startYear: "", endYear: "" },
        ],
        subjectsPassed: [{ name: "", grade: "" }],
        councilRegistrations: [],
        password: "",
        confirmPassword: "",
      },
      postSecondaryEducationRows: [{}],
      pseShowOtherName: [false],
      pseIsSpecialized: [false],
      additionalQualificationsRows: [],
      employmentHistoryRows: [{}],
      ehIsGovernment: [false],
      personalReferenceRows: [{}],
      schoolsAttendedRows: [{}],
      examinationPassedRows: [{}],
      subjectsPassedRows: [{}],
      councilRegistrationRows: [],
      showPassword: false,
      showConfirm: false,
      prefillReady: true,
    };
  },

  computed: {
    editMode() {
      return !!this.$route?.query?.editId;
    },
    passwordRules() {
      return [
        (v) => !!v || "Password is required.",
        (v) =>
          (v && v.length >= 8) || "Password must be at least 8 characters.",
      ];
    },
    confirmPasswordRules() {
      return [
        (v) => !!v || "Please confirm your password.",
        (v) => v === this.form.password || "Passwords do not match.",
      ];
    },
  },

  methods: {
    prefillFromResource(resource) {
      const exts = resource.extension || [];
      const get = (suffix, field = "valueString") => {
        const e = exts.find((x) => x.url.endsWith("/" + suffix));
        return e ? e[field] ?? null : null;
      };
      const getCoding = (suffix) => {
        const e = exts.find((x) => x.url.endsWith("/" + suffix));
        return e?.valueCoding ?? null;
      };
      const getRef = (suffix) => {
        const e = exts.find((x) => x.url.endsWith("/" + suffix));
        return e?.valueReference ?? null;
      };
      const getNestedSub = (parentSuffix, subUrl, field = "valueString") => {
        const p = exts.find((x) => x.url.endsWith("/" + parentSuffix));
        const c = p?.extension?.find((x) => x.url === subUrl);
        return c ? c[field] ?? null : null;
      };
      const getNestedSubCoding = (parentSuffix, subUrl) => {
        const p = exts.find((x) => x.url.endsWith("/" + parentSuffix));
        const c = p?.extension?.find((x) => x.url === subUrl);
        return c?.valueCoding ?? null;
      };
      const allOf = (suffix) =>
        exts.filter((x) => x.url.endsWith("/" + suffix));
      const subOf = (entry, subUrl, field = "valueString") => {
        const c = entry?.extension?.find((x) => x.url === subUrl);
        return c ? c[field] ?? null : null;
      };

      // Simple string / date fields
      this.form.firstname = get("first-name") || "";
      this.form.middlename = get("middle-name") || "";
      this.form.surname = get("surname") || "";
      this.form.email = get("email") || "";
      this.form.phone = get("phone") || "";
      this.form.birthdate = get("birthdate", "valueDate") || "";
      this.form.birthplace = get("birth-place") || "";
      this.form.nationalid = get("national-id") || "";
      this.form.passportnumber = get("passport-number") || "";
      this.form.passportissuedate =
        get("passport-issue-date", "valueDate") || "";
      this.form.passportexpirydate =
        get("passport-expiry-date", "valueDate") || "";
      this.form.nameofchief = get("name-of-chief") || "";
      this.form.tin = get("tin") || "";
      this.form.citizencertificatenumber =
        get("citizen-certificate-number") || "";
      this.form.citizencertificateissuedate =
        get("citizen-certificate-issue-date", "valueDate") || "";

      // Coding fields (fhir-choice — pass the full valueCoding object)
      this.form.gender = getCoding("person-gender")?.code;
      this.form.maritalstatus = getCoding(
        "ihris-practitioner-marital-status",
      )?.code;
      this.form.disabled = getCoding("ihris-practitioner-disability")?.code;
      this.form.nationality =
        getCoding("ihris-practitioner-nationality")?.code ||
        getCoding("nationality")?.code;
      this.form.passportissuecountry = getCoding(
        "passport-issue-country",
      )?.code;
      this.form.borninlesotho = getCoding("born-in-lesotho")?.code;
      this.form.convictedofcriminaloffense = getCoding(
        "convicted-of-criminal-offense",
      )?.code;
      this.form.dismissedfromservicebefore = getCoding(
        "dismissed-from-service-before",
      )?.code;
      this.form.spousenationality = getNestedSubCoding(
        "spouse-particulars",
        "nationality",
      )?.code;

      // Reference fields
      this.form.presentaddress = getRef("present-address");
      this.form.residence = getRef("ihris-practitioner-residence");
      this.form.birthdistrict = getRef("birth-district");

      // Nested single objects
      this.form.fathername = getNestedSub("father-particulars", "name") || "";
      this.form.fatherbirthplace =
        getNestedSub("father-particulars", "birthplace") || "";
      this.form.fatheroccupation =
        getNestedSub("father-particulars", "occupation") || "";
      this.form.fatheraddress =
        getNestedSub("father-particulars", "address") || "";
      this.form.spousename = getNestedSub("spouse-particulars", "name") || "";

      // Repeating: Post-Secondary Education
      const pseExts = allOf("post-secondary-education");
      if (pseExts.length) {
        this.form.postSecondaryEducation = pseExts.map((e) => ({
          institutionName: subOf(e, "institution-name") || "",
          country: subOf(e, "country", "valueCoding")?.code || "",
          dateOfEntry: subOf(e, "date-of-entry", "valueDate") || "",
          dateOfLeaving: subOf(e, "date-of-leaving", "valueDate") || "",
          qualificationLevel:
            subOf(e, "qualification-level", "valueCoding")?.code || "",
          qualificationName:
            subOf(e, "qualification-name", "valueReference") || "",
          qualificationNameOther: subOf(e, "qualification-name-other") || "",
          nameKey: 0,
          qualificationDate: subOf(e, "qualification-date", "valueDate") || "",
          specialized: subOf(e, "specialized", "valueCoding")?.code || "",
          specialization: subOf(e, "specialization", "valueCoding")?.code || "",
          isHighestQualification:
            subOf(e, "is-highest-qualification", "valueCoding")?.code || "",
          distinctionsGained: (e.extension || [])
            .filter((x) => x.url === "distinctions-gained")
            .map((x) => x.valueString || "")
            .filter(Boolean),
        }));
        this.postSecondaryEducationRows = this.form.postSecondaryEducation.map(
          () => ({}),
        );
        // Register listeners and compute initial conditional states for all prefilled rows.
        // Row 0 is already registered in created(); start from 1.
        this.form.postSecondaryEducation.forEach((row, i) => {
          if (i > 0) {
            this.registerQualificationNameListener(i);
            this.registerSpecializedListener(i);
          }
          const qName = row.qualificationName;
          const isOther =
            qName === "Basic/otherqualificationname" ||
            qName?.reference === "Basic/otherqualificationname";
          this.$set(this.pseShowOtherName, i, !!isOther);

          const spec = row.specialized;
          const isSpec = !!(spec && (spec.endsWith("#yes") || spec === "yes"));
          this.$set(this.pseIsSpecialized, i, isSpec);
        });
      }

      // Repeating: Additional Qualifications
      const aqExts = allOf("additional-qualifications");
      if (aqExts.length) {
        this.form.additionalQualifications = aqExts.map((e) => ({
          qualificationName: subOf(e, "qualification-name") || "",
          dateObtained: subOf(e, "date-obtained", "valueDate") || "",
          notes: subOf(e, "notes") || "",
        }));
        this.additionalQualificationsRows = this.form.additionalQualifications.map(
          () => ({}),
        );
      }

      // Repeating: Employment History
      const ehExts = allOf("employment-history");
      if (ehExts.length) {
        this.form.employmentHistory = ehExts.map((e) => ({
          employerCategory:
            subOf(e, "employer-category", "valueCoding")?.code || null,
          governmentDepartment: subOf(e, "government-department") || "",
          grade: subOf(e, "grade") || "",
          name: subOf(e, "name") || "",
          address: subOf(e, "address") || "",
          capacity: subOf(e, "capacity") || "",
          dutiesNature: subOf(e, "duties-nature") || "",
          startDate: subOf(e, "start-date", "valueDate") || "",
          endDate: subOf(e, "end-date", "valueDate") || "",
          salary: String(subOf(e, "salary", "valueDecimal") || ""),
          reasonForLeaving: subOf(e, "reason-for-leaving") || "",
          noticePeriod: subOf(e, "notice-period") || "",
          acting: subOf(e, "acting", "valueCoding")?.code || null,
        }));
        this.employmentHistoryRows = this.form.employmentHistory.map(
          () => ({}),
        );
        // Register listeners and compute initial conditional states for prefilled rows.
        // Row 0 is already registered in created(); start from 1.
        this.form.employmentHistory.forEach((row, i) => {
          if (i > 0) this.registerEmployerCategoryListener(i);
          const cat = row.employerCategory;
          const isGov = !!(
            cat &&
            (cat.code === "government" ||
              (typeof cat === "string" &&
                (cat.endsWith("#government") || cat === "government")))
          );
          this.$set(this.ehIsGovernment, i, isGov);
        });
      }

      // Repeating: Personal References
      const prExts = allOf("personal-reference");
      if (prExts.length) {
        this.form.personalReferences = prExts.map((e) => ({
          name: subOf(e, "name") || "",
          address: subOf(e, "address") || "",
          occupation: subOf(e, "occupation") || "",
          period: subOf(e, "period") || "",
        }));
        this.personalReferenceRows = this.form.personalReferences.map(
          () => ({}),
        );
      }

      // Repeating: Schools Attended
      const saExts = allOf("schools-attended");
      if (saExts.length) {
        this.form.schoolsAttended = saExts.map((e) => ({
          name: subOf(e, "name") || "",
          dateOfEntry: subOf(e, "date-of-entry", "valueDate") || "",
          dateOfLeaving: subOf(e, "date-of-leaving", "valueDate") || "",
        }));
        this.schoolsAttendedRows = this.form.schoolsAttended.map(() => ({}));
      }

      // Repeating: Examination Passed
      const epExts = allOf("examination-passed");
      if (epExts.length) {
        this.form.examinationPassed = epExts.map((e) => ({
          name: subOf(e, "name") || "",
          grade: subOf(e, "grade") || "",
          startYear: subOf(e, "start-year", "valueDate") || "",
          endYear: subOf(e, "end-year", "valueDate") || "",
        }));
        this.examinationPassedRows = this.form.examinationPassed.map(
          () => ({}),
        );
      }

      // Repeating: Subjects Passed
      const spExts = allOf("subject-passed");
      if (spExts.length) {
        this.form.subjectsPassed = spExts.map((e) => ({
          name: subOf(e, "name") || "",
          grade: subOf(e, "grade") || "",
        }));
        this.subjectsPassedRows = this.form.subjectsPassed.map(() => ({}));
      }

      // Repeating: Council Registration (optional, multiple)
      const crExts = allOf("council-registration");
      if (crExts.length) {
        this.form.councilRegistrations = crExts.map((e) => ({
          council: subOf(e, "council", "valueCoding")?.code || "",
          registrationNumber: subOf(e, "registration-number") || "",
          registrationDate: subOf(e, "registration-date", "valueDate") || "",
          licenseStatus: subOf(e, "license-status", "valueCoding")?.code || "",
        }));
        this.councilRegistrationRows = this.form.councilRegistrations.map(
          () => ({}),
        );
      }
    },

    async submitForm() {
      this.$refs.form.validate();
      if (!this.valid) return;

      this.saving = true;
      try {
        this.fhir = {
          password: this.form.password,
        };
        await this.processFHIR();

        if (this.editMode) {
          // Profile update — just show success and return to profile
          this.showSnackbar("Profile updated successfully.", "success");
          this.$router.push({
            path: "/custom/applicant-profile",
            query: {
              id: this.$route.query.editId,
              path: "/lesotho/components/recruitment",
            },
          });
        } else {
          // New account — log the user in automatically
          this.showSnackbar(
            "Account created successfully. Logging you in…",
            "success",
          );

          // Logout the current guest session
          await fetch("/auth/logout");
          this.$store.commit("logout");

          // Auto-login with the new credentials (username = email)
          const formData = new URLSearchParams();
          formData.append("username", this.form.email);
          formData.append("password", this.form.password);
          const loginResponse = await fetch("/auth/login", {
            method: "POST",
            headers: { "Content-Type": "application/x-www-form-urlencoded" },
            body: formData,
          });

          // Commit the logged-in user to the store directly rather than
          // relying on the "updateconfig" event bus listener — that
          // listener's store update is async (two chained fetches in
          // App.vue) and isn't awaited here, so the router.push below
          // used to fire before $store.state.user.loggedin was actually
          // set, leaving the destination page rendering as a guest.
          if (loginResponse.ok) {
            const loginData = await loginResponse.json();
            const userResource = loginData.user;
            const user = { obj: userResource, name: "Unknown" };
            if (userResource?.resource) {
              const roleExt = userResource.resource.extension?.find(
                (ext) =>
                  ext.url ===
                  "http://ihris.org/fhir/StructureDefinition/ihris-assign-role",
              );
              if (roleExt) {
                user.role = roleExt.valueReference.reference.split("/").pop();
              }
              if (userResource.resource.name?.[0]?.text) {
                user.name = userResource.resource.name[0].text;
              }
            }
            this.$store.commit("login", user);
          }

          eventBus.$emit("updateconfig");

          // Redirect to application form if advertId exists, otherwise home
          const advertId = this.$route.query && this.$route.query.advertId;
          // setTimeout(() => {

          // }, 2000);
          if (advertId) {
            this.$router.push({
              path: "/custom/apply-for-position",
              query: {
                path: "/lesotho/components/recruitment",
                advertId: advertId,
              },
            });
          } else {
            this.$router.push({ path: "/" });
          }
        }
      } catch (err) {
        console.error("submitForm error:", err);
        this.showSnackbar(
          this.editMode
            ? "Failed to update profile. Please try again."
            : "Failed to create account. Please try again.",
          "error",
        );
      } finally {
        this.saving = false;
      }
    },

    registerQualificationNameListener(index) {
      const eventName = `Basic.post-secondary-education[${index}].qualification-name`;
      eventBus.$on(eventName, (val) => {
        if (this.form.postSecondaryEducation[index] !== undefined) {
          // Store as object so setupData's source.data.reference resolves
          // correctly and avoids the double-emit bug on first selection.
          this.form.postSecondaryEducation[index].qualificationName = {
            reference: val,
          };
        }
        const isOther = val === "Basic/otherqualificationname";
        this.$set(this.pseShowOtherName, index, !!isOther);
      });
    },

    registerSpecializedListener(index) {
      const eventName = `Basic.post-secondary-education[${index}].specialized`;
      eventBus.$on(eventName, (val) => {
        if (this.form.postSecondaryEducation[index] !== undefined) {
          this.form.postSecondaryEducation[index].specialized = val;
        }
        const isSpec = !!(val && (val.endsWith("#yes") || val === "yes"));
        this.$set(this.pseIsSpecialized, index, isSpec);
      });
    },

    isSpecialized(index) {
      const val = this.form.postSecondaryEducation[index]?.specialized;
      if (!val) return false;
      return val.endsWith("#yes") || val === "yes";
    },

    registerEmployerCategoryListener(index) {
      const eventName = `Basic.employment-history[${index}].employer-category`;
      eventBus.$on(eventName, (val) => {
        if (this.form.employmentHistory[index] !== undefined) {
          this.form.employmentHistory[index].employerCategory = val;
        }
        const isGov = !!(
          val &&
          (val.endsWith("#government") || val === "government")
        );
        this.$set(this.ehIsGovernment, index, isGov);
      });
    },

    showSnackbar(text, color) {
      this.snackbar = { show: true, text: text, color: color || "success" };
    },

    scrollTo(id) {
      const el = document.getElementById(id);
      if (el) el.scrollIntoView({ behavior: "smooth" });
    },

    goBack() {
      this.$router.push({
        path: "/custom/advertised-positions",
        query: { path: "/lesotho/components/recruitment" },
      });
    },
    addPostSecondaryEducationRow() {
      const newIndex = this.postSecondaryEducationRows.length;
      this.registerQualificationNameListener(newIndex);
      this.registerSpecializedListener(newIndex);
      this.$set(this.pseShowOtherName, newIndex, false);
      this.$set(this.pseIsSpecialized, newIndex, false);
      this.postSecondaryEducationRows.push({});
      this.form.postSecondaryEducation.push({
        institutionName: "",
        country: "",
        dateOfEntry: "",
        dateOfLeaving: "",
        qualificationLevel: "",
        qualificationName: "",
        qualificationNameOther: "",
        qualificationDate: "",
        specialized: "",
        specialization: "",
        isHighestQualification: "",
        distinctionsGained: [],
        nameKey: 0,
      });
    },

    addDistinction(pseIndex) {
      this.form.postSecondaryEducation[pseIndex].distinctionsGained.push("");
    },

    removeDistinction(pseIndex, dgIndex) {
      this.form.postSecondaryEducation[pseIndex].distinctionsGained.splice(
        dgIndex,
        1,
      );
    },

    removePostSecondaryEducationRow(index) {
      if (this.postSecondaryEducationRows.length > 1) {
        this.postSecondaryEducationRows.splice(index, 1);
        this.form.postSecondaryEducation.splice(index, 1);
        this.pseShowOtherName.splice(index, 1);
        this.pseIsSpecialized.splice(index, 1);
      }
    },

    addAdditionalQualificationsRow() {
      this.additionalQualificationsRows.push({});
      this.form.additionalQualifications.push({
        qualificationName: "",
        dateObtained: "",
        notes: "",
      });
    },

    removeAdditionalQualificationsRow(index) {
      this.additionalQualificationsRows.splice(index, 1);
      this.form.additionalQualifications.splice(index, 1);
    },

    addEmploymentHistoryRow() {
      const newIndex = this.employmentHistoryRows.length;
      this.registerEmployerCategoryListener(newIndex);
      this.$set(this.ehIsGovernment, newIndex, false);
      this.employmentHistoryRows.push({});
      this.form.employmentHistory.push({
        employerCategory: null,
        governmentDepartment: "",
        grade: "",
        name: "",
        address: "",
        capacity: "",
        dutiesNature: "",
        startDate: "",
        endDate: "",
        salary: "",
        reasonForLeaving: "",
        noticePeriod: "",
        acting: null,
      });
    },

    removeEmploymentHistoryRow(index) {
      if (this.employmentHistoryRows.length > 1) {
        this.employmentHistoryRows.splice(index, 1);
        this.form.employmentHistory.splice(index, 1);
        this.ehIsGovernment.splice(index, 1);
      }
    },

    addPersonalReferenceRow() {
      if (this.personalReferenceRows.length < 3) {
        this.personalReferenceRows.push({});
        this.form.personalReferences.push({
          name: "",
          address: "",
          occupation: "",
          period: "",
        });
      }
    },

    removePersonalReferenceRow(index) {
      if (this.personalReferenceRows.length > 1) {
        this.personalReferenceRows.splice(index, 1);
        this.form.personalReferences.splice(index, 1);
      }
    },

    addSchoolsAttendedRow() {
      this.schoolsAttendedRows.push({});
      this.form.schoolsAttended.push({
        name: "",
        dateOfEntry: "",
        dateOfLeaving: "",
      });
    },
    removeSchoolsAttendedRow(index) {
      if (this.schoolsAttendedRows.length > 1) {
        this.schoolsAttendedRows.splice(index, 1);
        this.form.schoolsAttended.splice(index, 1);
      }
    },

    addExaminationPassedRow() {
      this.examinationPassedRows.push({});
      this.form.examinationPassed.push({
        name: "",
        grade: "",
        startYear: "",
        endYear: "",
      });
    },
    removeExaminationPassedRow(index) {
      if (this.examinationPassedRows.length > 1) {
        this.examinationPassedRows.splice(index, 1);
        this.form.examinationPassed.splice(index, 1);
      }
    },

    addSubjectsPassedRow() {
      this.subjectsPassedRows.push({});
      this.form.subjectsPassed.push({ name: "", grade: "" });
    },
    removeSubjectsPassedRow(index) {
      if (this.subjectsPassedRows.length > 1) {
        this.subjectsPassedRows.splice(index, 1);
        this.form.subjectsPassed.splice(index, 1);
      }
    },

    addCouncilRegistrationRow() {
      this.councilRegistrationRows.push({});
      this.form.councilRegistrations.push({
        council: "",
        registrationNumber: "",
        registrationDate: "",
        licenseStatus: "",
      });
    },

    removeCouncilRegistrationRow(index) {
      this.councilRegistrationRows.splice(index, 1);
      this.form.councilRegistrations.splice(index, 1);
    },

    goToLogin() {
      this.$router.push({ path: "/" });
    },
    cancel() {
      this.$router.push({ path: "/" });
    },
  },
  components: {
    "fhir-string": () => import("@/components/fhir/fhir-string"),
    "fhir-decimal": () => import("@/components/fhir/fhir-decimal"),
    "fhir-choice": () => import("@/components/fhir/fhir-choice"),
    "fhir-reference": () => import("@/components/fhir/fhir-reference"),
    "fhir-date": () => import("@/components/fhir/fhir-date"),
    "ihris-questionnaire-section": () =>
      import("@/components/ihris/ihris-questionnaire-section"),
  },
  created() {
    eventBus.$on("Basic.nationality", (val) => {
      this.form.nationality = val;
    });
    eventBus.$on("Basic.borninlesotho", (val) => {
      this.form.borninlesotho = val;
    });
    eventBus.$on("Basic.email", (val) => {
      this.form.email = val;
    });
    this.registerQualificationNameListener(0);
    this.registerSpecializedListener(0);
    this.registerEmployerCategoryListener(0);
    const editId = this.$route?.query?.editId;
    if (editId) {
      this.fhirId = editId;
      this.prefillReady = false;
      fetch(`/fhir/Basic/${editId}`)
        .then((r) => r.json())
        .then((data) => {
          const resource =
            data.resourceType === "Bundle" ? data.entry?.[0]?.resource : data;
          if (resource) this.prefillFromResource(resource);
        })
        .catch((e) => console.error("prefill error:", e))
        .finally(() => {
          this.prefillReady = true;
        });
    }
  },

  // ── Prefill helpers ─────────────────────────────────────────────
  // (defined outside created so they are reusable methods)
  // Note: placed here as they are needed only for edit mode
};
</script>

